# Maze search: explore paths
maze = {"start": ["A", "B"], "A": ["C"], "B": ["C"], "C": ["exit"]}
path = ["start"]
while path[-1] != "exit":
    path.append(maze[path[-1]][0])
print(f"Path: {' → '.join(path)}")

graph = {
    'A': ['B', 'C'],
    'B': ['A', 'D'],
    'C': ['A', 'D'],
    'D': ['B', 'C']
}
heuristic = {'A': 3, 'B': 2, 'C': 2, 'D': 0}
start, goal = 'A', 'D'
# A*: choose node with lowest f(n) = g(n) + h(n)
frontier = [(0 + heuristic[start], 0, start, [start])]
visited = set()
while frontier:
    frontier.sort(key=lambda x: x[0])
    f, g, node, path = frontier.pop(0)
    if node == goal:
        print(f'Found: {" → ".join(path)}')
        break
    if node in visited:
        continue
    visited.add(node)
    for nxt in graph[node]:
        if nxt not in visited:
            new_g = g + 1
            frontier.append((new_g + heuristic[nxt], new_g, nxt, path + [nxt]))

